<h2>{{ $plan?'Edit managed server plan':'Add managed server plan' }}</h2><p>Map a provider SKU and calculate the public monthly price.</p><div class="admin-dialog-grid"><label><span>Provider</span><select name="provider"><option value="digitalocean" @selected($plan?->provider==='digitalocean')>DigitalOcean</option><option value="hetzner" @selected($plan?->provider==='hetzner')>Hetzner</option></select></label><label><span>Provider plan ID</span><input name="provider_plan_id" value="{{ $plan?->provider_plan_id }}" placeholder="s-2vcpu-2gb / cx22" required></label><label><span>Display name</span><input name="name" value="{{ $plan?->name }}" required></label><label><span>Currency</span><input name="currency" value="{{ $plan?->currency??'USD' }}" required></label><label><span>vCPU</span><input type="number" name="cpu_cores" value="{{ $plan?->cpu_cores??2 }}" required></label><label><span>Memory MB</span><input type="number" name="memory_mb" value="{{ $plan?->memory_mb??2048 }}" required></label><label><span>Disk GB</span><input type="number" name="disk_gb" value="{{ $plan?->disk_gb??50 }}" required></label><label><span>Bandwidth GB</span><input type="number" name="bandwidth_gb" value="{{ $plan?->bandwidth_gb??1000 }}"></label><label><span>Provider cost / month</span><input type="number" step=".01" name="monthly_cost" value="{{ $plan?number_format($plan->monthly_cost/100,2,'.',''):'10.00' }}" required></label><label><span>Markup percentage</span><input type="number" name="markup_percentage" value="{{ $plan?->markup_percentage??25 }}" required></label><label class="wide"><span>Regions (comma separated)</span><input name="regions" value="{{ implode(', ', $plan?->regions??['fra1','nyc3']) }}" required></label><label class="wide"><span>Images (comma separated)</span><input name="images" value="{{ implode(', ', $plan?->images??['ubuntu-24.04','ubuntu-22.04']) }}" required></label></div><div class="admin-switches"><label><span><strong>Featured plan</strong><small>Highlight this option to customers.</small></span><input type="checkbox" name="featured" value="1" @checked($plan?->featured)></label><label><span><strong>Published</strong><small>Allow customers to provision this SKU.</small></span><input type="checkbox" name="active" value="1" @checked($plan?->active??true)></label></div>
